"""Committed Session v4 artifacts generated by the pinned TypeScript implementation."""

from __future__ import annotations

import hashlib
import json
from collections.abc import AsyncIterator
from pathlib import Path
from typing import Any

import pytest
import pytest_asyncio
from deepseek_cordis import Context

from deskagents.session import persistence_jsonl
from deskagents.session.persistence import SessionPersistence

FIXTURES = Path(__file__).resolve().parents[2] / "fixtures" / "dsh_v4"
MANIFEST: dict[str, Any] = json.loads((FIXTURES / "MANIFEST.json").read_text())
ROOT = Path(__file__).resolve().parents[3]


@pytest_asyncio.fixture
async def contexts() -> AsyncIterator[list[Context]]:
    mounted: list[Context] = []
    yield mounted
    for ctx in mounted:
        await ctx.fiber.dispose()


@pytest.mark.parametrize("artifact", MANIFEST["artifacts"])
def test_dsh_fixture_checksum(artifact: dict[str, str]) -> None:
    content = (FIXTURES / artifact["path"]).read_bytes()
    assert hashlib.sha256(content).hexdigest() == artifact["sha256"]


def test_dsh_fixture_pin_matches_upstream_map() -> None:
    upstream = json.loads((ROOT / "docs" / "upstream.json").read_text())
    assert MANIFEST["upstreamCommit"] == upstream["upstream"]["commit"]


@pytest.mark.parametrize("artifact", MANIFEST["artifacts"])
@pytest.mark.asyncio
async def test_python_opens_and_replays_dsh_fixture(
    artifact: dict[str, str], contexts: list[Context]
) -> None:
    compression = artifact["compression"]
    ctx = Context()
    contexts.append(ctx)
    await ctx.plugin(
        persistence_jsonl,
        {"root": str(FIXTURES / compression), "compression": compression},
    )
    backend = ctx.get("sessionPersistence")
    assert isinstance(backend, SessionPersistence)
    handle = await backend.open(MANIFEST["sessionId"], "read")
    result = await handle.read()
    assert len(result.events) == MANIFEST["eventCount"]
    assert [event["type"] for event in result.events] == ["turn/start", "turn/end"]
    await handle.close()
